package ledger

import (
	"fmt"
	"testing"
)

func TestFmtWidth(t *testing.T) {
	t.Logf("ascii: [%s]", fmt.Sprintf("%-25s", "Buy present"))
	t.Logf("nonascii: [%s]", fmt.Sprintf("%-5s", "héllo"))
	t.Logf("right: [%s]", fmt.Sprintf("%13s", "($10.00)"))
}

package ledger

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// Entry represents a single ledger entry.
type Entry struct {
	Date        string // "YYYY-MM-DD"
	Description string
	Change      int // in cents
}

// locale captures the locale-specific formatting rules for the ledger.
type locale struct {
	name        string
	dateLabel   string
	descLabel   string
	changeLabel string
	dutch       bool
}

var locales = map[string]locale{
	"en-US": {name: "en-US", dateLabel: "Date", descLabel: "Description", changeLabel: "Change"},
	"nl-NL": {name: "nl-NL", dateLabel: "Datum", descLabel: "Omschrijving", changeLabel: "Verandering", dutch: true},
}

var symbols = map[string]string{
	"USD": "$",
	"EUR": "€",
}

// FormatLedger renders the given entries as a formatted ledger table for the
// supplied currency and locale. The input slice is not modified.
func FormatLedger(currency string, loc string, entries []Entry) (string, error) {
	l, ok := locales[loc]
	if !ok {
		return "", errors.New("invalid locale")
	}
	symbol, ok := symbols[currency]
	if !ok {
		return "", errors.New("invalid currency")
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var sb strings.Builder
	sb.WriteString(l.header())
	for _, e := range sorted {
		line, err := l.formatLine(symbol, e)
		if err != nil {
			return "", err
		}
		sb.WriteString(line)
	}
	return sb.String(), nil
}

func (l locale) header() string {
	return fmt.Sprintf("%-10s | %-25s | %s\n", l.dateLabel, l.descLabel, l.changeLabel)
}

func (l locale) formatLine(symbol string, e Entry) (string, error) {
	date, err := l.formatDate(e.Date)
	if err != nil {
		return "", err
	}
	desc := e.Description
	if len(desc) > 25 {
		desc = desc[:22] + "..."
	}
	change := l.formatChange(symbol, e.Change)
	return fmt.Sprintf("%-10s | %-25s | %13s\n", date, desc, change), nil
}

func (l locale) formatDate(date string) (string, error) {
	if len(date) != 10 || date[4] != '-' || date[7] != '-' {
		return "", errors.New("invalid date")
	}
	year, month, day := date[0:4], date[5:7], date[8:10]
	if l.dutch {
		return day + "-" + month + "-" + year, nil
	}
	return month + "/" + day + "/" + year, nil
}

func (l locale) formatChange(symbol string, cents int) string {
	negative := cents < 0
	if negative {
		cents = -cents
	}
	thousandsSep, decimalSep := ",", "."
	if l.dutch {
		thousandsSep, decimalSep = ".", ","
	}
	number := formatCents(cents, thousandsSep, decimalSep)
	if l.dutch {
		suffix := " "
		if negative {
			suffix = "-"
		}
		return symbol + " " + number + suffix
	}
	if negative {
		return "(" + symbol + number + ")"
	}
	return symbol + number + " "
}

// formatCents renders a non-negative cents amount with the supplied thousands
// and decimal separators, e.g. 123456 -> "1,234.56".
func formatCents(cents int, thousandsSep, decimalSep string) string {
	whole := cents / 100
	frac := cents % 100
	ws := strconv.Itoa(whole)
	var grouped strings.Builder
	for i := 0; i < len(ws); i++ {
		if i > 0 && (len(ws)-i)%3 == 0 {
			grouped.WriteString(thousandsSep)
		}
		grouped.WriteByte(ws[i])
	}
	return grouped.String() + decimalSep + fmt.Sprintf("%02d", frac)
}

// Change log for this refactoring (per the exercise instructions):
//
//  1. Replaced the recursive "validate by formatting a dummy entry" hack with
//     explicit up-front validation of the locale and currency.
//  2. Replaced the hand-rolled selection sort (with its bool->int maps) with a
//     clear sort.Slice on a copy of the input, keeping the input unmodified.
//  3. Removed the goroutine/channel fan-out that formatted rows in parallel;
//     rows are now formatted sequentially in sorted order.
//  4. Extracted the duplicated per-locale number formatting into a single
//     formatCents helper and a locale method, removing the two near-identical
//     branches.
//  5. Moved header and row layout into locale methods using fmt width
//     specifiers instead of manual strings.Repeat padding.
